   "id": "z9c267906",
   "sez": "spazio",
   "titolo": "Il rover Perseverance stabilisce il record di guida extraterrestre su Marte",
   "orig": "NASA’s Perseverance rover breaks record for off-planet driving on Mars",
   "lead": "Il rover robotico Perseverance della NASA ha stabilito il primato assoluto di distanza percorsa da un veicolo sulla superficie di un corpo celeste diverso dalla Terra, raggiungendo quota quarantacinque virgola due chilometri, pari a ventotto virgola uno miglia, dal suo arrivo sul pianeta rosso nel 2021. Il laboratorio mobile a sei ruote, delle dimensioni di un'automobile, ha toccato questo traguardo storico dopo cinque anni e mezzo di attività scientifica dedicati alla ricerca di tracce di vita passata e all'esplorazione del territorio marziano.",
   "more": [
    "Perseverance è un veicolo autonomo inviato dall'agenzia spaziale statunitense per studiare il cratere Jezero su Marte. Dotato di bracci robotici, fotocamere avanzate e trapani per carotaggio, raccoglie campioni di roccia destinati a future missioni di rientro a terra per chiarire la storia geologica del pianeta."
   ],
