   "sez": "prima",
   "titolo": "Il Fondo Monetario Internazionale stima la crescita globale al 3,1% con l'apporto dell'IA",
   "orig": "FMI prevede crescita globale al 3,1% nel 2026, eurozona all'1,1%, Italia a +0,8%",
   "lead": "Il Fondo Monetario Internazionale stima per il 2026 una crescita economica globale pari al 3,1%, con un incremento dell'1,1% nell'eurozona e dello 0,8% per l'Italia. La capo economista Silvana Tenreyro ha osservato che la resilienza mostrata finora dai sistemi economici sta raggiungendo i propri limiti, sollecitando il passaggio dalla gestione delle emergenze a politiche di ricostruzione. L'istituzione sottolinea inoltre che la spinta proveniente dagli investimenti nell'intelligenza artificiale sostiene la produzione mondiale, compensando l'impatto dei conflitti ma rischiando di mantenere elevati i tassi d'interesse.",
   "more": [
    "Il Fondo Monetario Internazionale è un'organizzazione finanziaria internazionale che monitora la stabilità economica globale e fornisce previsioni macroeconomiche per orientare le politiche fiscali degli Stati membri. I suoi rapporti periodici valutano fattori come inflazione, produttività e andamento del debito pubblico."
   ],
